def _dispatch_command(
    args: argparse.Namespace,
    *,
    base_url: str,
    request_fn: RequestFn,
    json_output: bool,
    out: TextIO,
    err: TextIO,
) -> int:
    handler = getattr(args, "handler", None)

    if handler == "help":
        build_parser().print_help(out)
        return 0

    if handler == "experiments_create":
        notes = Path(args.notes_file).read_text(encoding="utf-8")
        config = Path(args.config_file).read_text(encoding="utf-8")
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
            "start_step": args.start_step,
            "stop_node": args.stop_node,
            "notes": notes,
            "config": config,
        }
        if args.stop_machine_path is not None:
            body["stop_machine_path"] = args.stop_machine_path
        endpoint = "/experiments/create"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_create_experiment(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "experiments_land":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
            "experiment_id": args.experiment_id,
        }
        endpoint = "/experiments/land"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_land_experiment(data, out)
            return 0
        if not json_output:
            _format_land_experiment(data, err)
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "create":
        body: dict[str, Any] = {
            "project": args.project,
            "quest_type": args.type,
            "name": args.name,
        }
        if args.slug is not None:
            body["slug"] = args.slug
        endpoint = "/create_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_create(data, base_url, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "run":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
        }
        if args.experiment_id is not None:
            body["experiment_id"] = args.experiment_id
        if args.max_steps is not None:
            body["max_steps"] = args.max_steps
        endpoint = "/run_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_run(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "upgrade":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
        }
        if args.experiment_id is not None:
            body["experiment_id"] = args.experiment_id
        endpoint = "/upgrade_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_upgrade(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "advance":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
        }
        if args.experiment_id is not None:
            body["experiment_id"] = args.experiment_id
        endpoint = "/advance_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_advance(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "land":
        if args.experiment_id is not None:
            body = {
                "project": args.project,
                "quest_type": args.type,
                "quest_number": args.number,
                "experiment_id": args.experiment_id,
            }
            endpoint = "/experiments/land"
            status, data = _send_request(
                request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_land_experiment(data, out)
                return 0
            if not json_output:
                _format_land_experiment(data, err)
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
            "target_branch": args.target_branch,
        }
        endpoint = "/land"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_land(data, out)
            return 0
        if not json_output:
            _format_land(data, err)
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "slices_init":
        if args.count < 1:
            raise CliValidationError("--count must be a positive integer")
        if len(args.slug) != args.count:
            raise CliValidationError("--slug must be provided exactly --count times")
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
            "count": args.count,
            "slugs": args.slug,
        }
        if args.collection is not None:
            body["collection"] = args.collection
        if args.experiment_id is not None:
            body["experiment_id"] = args.experiment_id
        endpoint = "/api/slices/init"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_slices_init(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler and handler.startswith("issues_"):
        _validate_scope(args.scope)
        _validate_slice_for_scope(args.scope, args.slice)

        project = args.project
        quest_type = args.type
        quest_number = args.number
        scope = args.scope
        slice_number = args.slice
        experiment_id = args.experiment_id

        if handler == "issues_list":
            _validate_list_status(args.status)
            endpoint = "/api/issues"
            query = _issue_query(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                experiment_id,
                {"status": args.status},
            )
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue_list(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_read":
            endpoint = f"/api/issues/{args.issue_id}"
            query = _issue_query(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                experiment_id,
            )
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                    responses = data.get("responses")
                    if isinstance(responses, list) and responses:
                        out.write("\nresponses:\n")
                        _format_responses_list({"responses": responses}, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_create":
            body_text = _read_text_source(args.body, args.body_file, "body")
            _validate_issue_status(args.status)
            endpoint = "/api/issues"
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                experiment_id,
                {"title": args.title, "body": body_text, "status": args.status},
            )
            status, data = _send_request(
                request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_edit":
            if args.body is not None and args.body_file is not None:
                raise CliValidationError("--body and --body-file are mutually exclusive")
            if args.status is None and args.title is None and args.body is None and args.body_file is None:
                raise CliValidationError(
                    "At least one of --status, --title, --body, or --body-file is required"
                )
            if args.status is not None:
                _validate_issue_status(args.status)
            endpoint = f"/api/issues/{args.issue_id}"
            extra: dict[str, Any] = {}
            if args.status is not None:
                extra["status"] = args.status
            if args.title is not None:
                extra["title"] = args.title
            if args.body is not None or args.body_file is not None:
                extra["body"] = _read_text_source(args.body, args.body_file, "body")
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                experiment_id,
                extra,
