            )

        if handler == "issues_create":
            body_text = _read_text_source(args.body, args.body_file, "body")
            _validate_issue_status(args.status)
            endpoint = "/api/issues"
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                scope,
