def _add_experiment_id_arg(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--experiment-id",
        default=None,
        help="Experiment id when operating in an experiment worktree",
    )


def _add_issue_file_args(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--file",
        required=True,
        dest="issue_file",
        help="Quest-relative issue file path declared by the workflow",
