            body["experiment_id"] = args.experiment_id
        endpoint = "/api/slices/init"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_slices_init(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler and handler.startswith("issues_"):
        project = args.project
        quest_type = args.type
        quest_number = args.number
        issue_file = args.issue_file
        experiment_id = args.experiment_id

        if handler == "issues_list":
            _validate_list_status(args.status)
            endpoint = "/api/issues"
            query = _issue_query(
                project,
                quest_type,
                quest_number,
                issue_file,
                experiment_id,
                {"status": args.status},
            )
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue_list(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_read":
            endpoint = f"/api/issues/{args.issue_id}"
            query = _issue_query(
                project,
                quest_type,
                quest_number,
                issue_file,
                experiment_id,
            )
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                    responses = data.get("responses")
                    if isinstance(responses, list) and responses:
                        out.write("\nresponses:\n")
                        _format_responses_list({"responses": responses}, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_create":
            body_text = _read_text_source(args.body, args.body_file, "body")
            _validate_issue_status(args.status)
            endpoint = "/api/issues"
            create_extra: dict[str, Any] = {
                "title": args.title,
                "body": body_text,
                "status": args.status,
            }
            if args.owner is not None:
                create_extra["owner_role"] = args.owner
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                issue_file,
                experiment_id,
                create_extra,
            )
            status, data = _send_request(
                request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
